import {svg,bounds,scale,axes,text,unique,esc} from '../gallery-utils.js';
export function render({data,params:p}){unique(data,['label']);const b=bounds(p);b.l=Math.min(p.width*.4,220);b.r=p.width-70;const d=[...data];if(p.sort!=='原顺序')d.sort((a,b)=>p.sort==='降序'?b.value-a.value:a.value-b.value);const x=scale([0,...d.map(d=>d.value)],b.l,b.r),slot=(b.b-b.t)/d.length;if(slot<18)throw Error('条目过多，请增大画布高度');let s=axes(b,x,null,{...p,yLabel:''});s+=`<path d="M${x(0)},${b.t}V${b.b}" stroke="#94a4b4"/>`;d.forEach((r,i)=>{const y=b.t+(i+.15)*slot;s+=`<rect x="${Math.min(x(0),x(r.value))}" y="${y}" width="${Math.abs(x(r.value)-x(0))}" height="${slot*.65}" fill="${esc(p.color)}"/>`+text(b.l-10,y+slot*.4,r.label,'text-anchor="end"')+text(x(r.value)+(r.value<0?-5:5),y+slot*.4,Number(r.value.toPrecision(4)),r.value<0?'text-anchor="end"':'');});return svg(p,s);}